alter table public.shift_change_requests add column if not exists target_response text not null default 'not_required';
alter table public.shift_change_requests add column if not exists target_responded_at timestamptz;
alter table public.shift_change_requests add column if not exists target_responded_by uuid references auth.users(id) on delete set null;
do $$begin if not exists(select 1 from pg_constraint where conname='shift_change_requests_target_response_check' and conrelid='public.shift_change_requests'::regclass) then alter table public.shift_change_requests add constraint shift_change_requests_target_response_check check(target_response in('not_required','pending','accepted','declined'));end if;end$$;

create or replace function public.submit_my_shift_change_request(p_shift_id uuid,p_request_type text,p_target_shift_id uuid default null,p_reason text default null)
returns jsonb language plpgsql security definer set search_path='pg_catalog','public' as $$
declare loc uuid:=public.current_location_id();eid uuid:=public.current_schedule_employee_id();src public.schedule_shifts%rowtype;target_emp uuid;rid uuid;
begin
 if auth.uid() is null or loc is null or eid is null then raise exception 'active employee login required';end if;if p_request_type not in('coverage','swap') then raise exception 'employee request type must be coverage or swap';end if;select * into src from public.schedule_shifts where id=p_shift_id and location_id=loc and employee_id=eid and status in('scheduled','covered') for share;if not found or src.ends_at<=now() then raise exception 'source shift is unavailable';end if;if src.schedule_period_id is not null and not public.is_schedule_department_published(src.schedule_period_id,src.role_id) then raise exception 'shift is not published';end if;if exists(select 1 from public.shift_change_requests q where q.location_id=loc and q.shift_id=src.id and q.requested_by_employee_id=eid and q.status='pending' and q.request_type=p_request_type) then raise exception 'you already have a pending request for this shift';end if;
 if p_request_type='coverage' then insert into public.shift_change_requests(location_id,shift_id,request_type,requested_by_employee_id,reason,status,requested_by,target_response) values(loc,src.id,'coverage',eid,left(nullif(trim(coalesce(p_reason,'')),''),2000),'pending',auth.uid(),'not_required') returning id into rid;perform public.notify_location_managers(loc,'staffing','Coverage request needs review','An employee requested coverage for a shift.','/schedule/pool',jsonb_build_object('request_id',rid,'shift_id',src.id,'type','coverage'));
 else if p_target_shift_id is null then raise exception 'trade requires a target shift';end if;select c.employee_id into target_emp from public.staff_trade_candidates(src.id)c where c.shift_id=p_target_shift_id limit 1;if target_emp is null then raise exception 'trade target is no longer eligible';end if;insert into public.shift_change_requests(location_id,shift_id,target_shift_id,request_type,requested_by_employee_id,target_employee_id,reason,status,requested_by,target_response) values(loc,src.id,p_target_shift_id,'swap',eid,target_emp,left(nullif(trim(coalesce(p_reason,'')),''),2000),'pending',auth.uid(),'pending') returning id into rid;perform public.notify_schedule_employee(loc,target_emp,'schedule','Shift trade needs your response','A coworker requested a reciprocal shift trade with you.','/schedule/pool',jsonb_build_object('request_id',rid,'shift_id',src.id,'target_shift_id',p_target_shift_id,'type','swap','response_needed',true));end if;
 return jsonb_build_object('request_id',rid,'status','pending','target_response',case when p_request_type='swap' then 'pending' else 'not_required' end);
end$$;

create or replace function public.respond_to_my_shift_trade(p_request_id uuid,p_accept boolean)
returns boolean language plpgsql security definer set search_path='pg_catalog','public' as $$
declare loc uuid:=public.current_location_id();eid uuid:=public.current_schedule_employee_id();q public.shift_change_requests%rowtype;target_shift public.schedule_shifts%rowtype;
begin if auth.uid() is null or loc is null or eid is null then raise exception 'active employee login required';end if;select * into q from public.shift_change_requests where id=p_request_id and location_id=loc and request_type='swap' and status='pending' and target_employee_id=eid and target_response='pending' for update;if not found then raise exception 'trade response is no longer available';end if;select * into target_shift from public.schedule_shifts where id=q.target_shift_id and location_id=loc for share;if not found or target_shift.employee_id is distinct from eid or target_shift.status not in('scheduled','covered') or target_shift.ends_at<=now() then raise exception 'your trade shift is no longer available';end if;update public.shift_change_requests set target_response=case when p_accept then 'accepted' else 'declined' end,target_responded_at=now(),target_responded_by=auth.uid(),status=case when p_accept then 'pending' else 'denied' end,updated_at=now() where id=q.id;if p_accept then perform public.notify_location_managers(loc,'staffing','Accepted shift trade needs review','Both employees accepted a reciprocal trade.','/schedule/pool',jsonb_build_object('request_id',q.id,'type','swap'));perform public.notify_schedule_employee(loc,q.requested_by_employee_id,'schedule','Coworker accepted your trade','Your trade is now waiting for manager approval.','/schedule/pool',jsonb_build_object('request_id',q.id,'type','swap','target_response','accepted'));else perform public.notify_schedule_employee(loc,q.requested_by_employee_id,'schedule','Coworker declined your trade','Your reciprocal shift trade was declined.','/schedule/pool',jsonb_build_object('request_id',q.id,'type','swap','target_response','declined'));end if;return true;end$$;

create or replace function public.cancel_my_shift_change_request(p_request_id uuid)
returns boolean language plpgsql security definer set search_path='pg_catalog','public' as $$
declare loc uuid:=public.current_location_id();eid uuid:=public.current_schedule_employee_id();q public.shift_change_requests%rowtype;
begin if auth.uid() is null or loc is null or eid is null then raise exception 'active employee login required';end if;select * into q from public.shift_change_requests where id=p_request_id and location_id=loc and requested_by_employee_id=eid and status='pending' for update;if not found then return false;end if;update public.shift_change_requests set status='cancelled',updated_at=now() where id=q.id;if q.request_type='swap' and q.target_employee_id is not null then perform public.notify_schedule_employee(loc,q.target_employee_id,'schedule','Shift trade cancelled','The coworker who requested this trade cancelled it.','/schedule/pool',jsonb_build_object('request_id',q.id,'type','swap','status','cancelled'));end if;return true;end$$;

create or replace function public.review_shift_change_request(p_request_id uuid,p_decision text)
returns boolean language plpgsql security definer set search_path='pg_catalog','public' as $$
declare r public.shift_change_requests%rowtype;a public.schedule_shifts%rowtype;b public.schedule_shifts%rowtype;loc uuid:=public.current_location_id();
begin if auth.uid() is null or public.current_app_role() not in('admin','manager') then raise exception 'manager access required';end if;if p_decision not in('approved','denied') then raise exception 'invalid decision';end if;select * into r from public.shift_change_requests where id=p_request_id and location_id=loc and status='pending' for update;if not found then return false;end if;if r.request_type='swap' and r.target_response not in('accepted','not_required') then raise exception 'coworker must accept the trade before manager review';end if;if p_decision='approved' then select * into a from public.schedule_shifts where id=r.shift_id and location_id=loc for update;if not found or a.ends_at<=now() then raise exception 'source shift is unavailable';end if;perform set_config('el_molino.published_schedule_rpc','1',true);if r.request_type in('callout','coverage') then update public.schedule_shifts set status='open',employee_id=null where id=a.id;if r.target_employee_id is not null then update public.schedule_shifts set employee_id=r.target_employee_id,status='covered',source='swap' where id=a.id;end if;elsif r.request_type='swap' then if r.target_shift_id is null then raise exception 'swap requires a target shift';end if;select * into b from public.schedule_shifts where id=r.target_shift_id and location_id=loc for update;if not found or b.ends_at<=now() or a.employee_id is null or b.employee_id is null then raise exception 'swap shifts are unavailable';end if;if r.requested_by_employee_id is distinct from a.employee_id then raise exception 'requester no longer owns source shift';end if;if r.target_employee_id is distinct from b.employee_id then raise exception 'target employee no longer owns target shift';end if;if a.role_id is not null and not exists(select 1 from public.employee_role_assignments x where x.employee_id=b.employee_id and x.role_id=a.role_id) then raise exception 'target employee is no longer qualified for source role';end if;if b.role_id is not null and not exists(select 1 from public.employee_role_assignments x where x.employee_id=a.employee_id and x.role_id=b.role_id) then raise exception 'requester is no longer qualified for target role';end if;if public.time_off_conflicts_shift(a.employee_id,loc,b.starts_at,b.ends_at,'approved') or public.time_off_conflicts_shift(b.employee_id,loc,a.starts_at,a.ends_at,'approved') then raise exception 'trade now conflicts with approved time off';end if;if exists(select 1 from public.schedule_shifts x where x.location_id=loc and x.employee_id=a.employee_id and x.id not in(a.id,b.id) and x.status in('scheduled','covered') and x.starts_at<b.ends_at and x.ends_at>b.starts_at) or exists(select 1 from public.schedule_shifts x where x.location_id=loc and x.employee_id=b.employee_id and x.id not in(a.id,b.id) and x.status in('scheduled','covered') and x.starts_at<a.ends_at and x.ends_at>a.starts_at) then raise exception 'trade now conflicts with another shift';end if;update public.schedule_shifts set employee_id=null,status='open' where id in(a.id,b.id);update public.schedule_shifts set employee_id=b.employee_id,status='covered',source='swap' where id=a.id;update public.schedule_shifts set employee_id=a.employee_id,status='covered',source='swap' where id=b.id;end if;end if;update public.shift_change_requests set status=p_decision,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=r.id;if r.requested_by_employee_id is not null then perform public.notify_schedule_employee(loc,r.requested_by_employee_id,'schedule','Shift request '||p_decision,initcap(r.request_type)||' request was '||p_decision||'.','/schedule/pool',jsonb_build_object('request_id',r.id,'decision',p_decision,'type',r.request_type));end if;if r.request_type='swap' and r.target_employee_id is not null and r.target_employee_id is distinct from r.requested_by_employee_id then perform public.notify_schedule_employee(loc,r.target_employee_id,'schedule','Shift swap '||p_decision,'A shift swap involving you was '||p_decision||'.','/schedule/pool',jsonb_build_object('request_id',r.id,'decision',p_decision));end if;return true;end$$;

grant execute on function public.submit_my_shift_change_request(uuid,text,uuid,text),public.respond_to_my_shift_trade(uuid,boolean),public.cancel_my_shift_change_request(uuid) to authenticated;
revoke execute on function public.submit_my_shift_change_request(uuid,text,uuid,text),public.respond_to_my_shift_trade(uuid,boolean),public.cancel_my_shift_change_request(uuid) from anon,public;
revoke insert,update,delete on public.shift_change_requests from authenticated;
